#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>

/* Helper: safe multiplication modulo using 128‑bit intermediate */
static int64_t mul_mod(int64_t a, int64_t b, int64_t mod)
{
    __int128 prod = (__int128)a * (__int128)b;
    prod %= mod;
    return (int64_t)prod;
}

/* Helper: exponentiation by squaring (modular) */
static int64_t mod_pow(int64_t base, int64_t exp, int64_t mod)
{
    /* make base non‑negative */
    base %= mod;
    if (base < 0)
        base += mod;

    int64_t result = 1 % mod;          /* same as (1 % mod) */
    while (exp > 0) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Validate that the whole string was consumed by strtoll */
static int parse_number(const char *s, int64_t *out)
{
    char *endptr = NULL;
    errno = 0;
    *out = strtoll(s, &endptr, 10);
    if (errno != 0)
        return 0;                     /* overflow / underflow */
    if (endptr == s)                  /* no conversion */
        return 0;
    if (*endptr != '\0')              /* extra characters */
        return 0;
    return 1;
}

int main(int argc, char **argv)
{
    /* ---------- argument count check ---------- */
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    int64_t base, exp, mod;

    /* ---------- parse and validate each argument ---------- */
    if (!parse_number(argv[1], &base) ||
        !parse_number(argv[2], &exp) ||
        !parse_number(argv[3], &mod)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- modulus checks ---------- */
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- exponent check ---------- */
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    /* ---------- compute modular exponentiation ---------- */
    int64_t result = mod_pow(base, exp, mod);
    printf("result=%" PRId64 "\n", result);
    return 0;
}
